  if bf > 1:
    if balance_factor(z.left) < 0:
      z.left = left_rotate(z.left)
    return right_rotate(z)
  if bf < -1:
    if balance_factor(z.right) > 0:
      z.right = right_rotate(z.right)
    return left_rotate(z)
