def is_avl_regular(root):
    def is_bst(node, low, high):
        if node is None:
            return True
        if not (low < node.key < high):
            return False
        return is_bst(node.left, low, node.key) and is_bst(node.right, node.key, high)

    def height(node):
        if node is None:
            return 0
        return 1 + max(height(node.left), height(node.right))

    def balanced(node):
        if node is None:
            return True
        if abs(height(node.left) - height(node.right)) > 1:
            return False
        return balanced(node.left) and balanced(node.right)

    return is_bst(root, float('-inf'), float('inf')) and balanced(root)

