def is_avl_optimal(root):
    if root is None:
        return True

    height = {None: 0}
    stack = [(root, float('-inf'), float('inf'), False)]

    while stack:
        node, low, high, seen = stack.pop()
        if node is None:
            continue

        if seen:
            if not (low < node.key < high):
                return False

            left_height = height[node.left]
            right_height = height[node.right]
            if abs(left_height - right_height) > 1:
                return False

            height[node] = 1 + max(left_height, right_height)
        else:
            stack.append((node, low, high, True))
            stack.append((node.right, node.key, high, False))
            stack.append((node.left, low, node.key, False))

    return True

