        self.key = key
        self.left = None
        self.right = None
        self.height = 1

def height(node):
    if node is None:
        return 0
    return node.height

def update(node):
    node.height = 1 + max(height(node.left), height(node.right))

def balance_factor(node):
    if node is None:
        return 0
    return height(node.left) - height(node.right)

def left_rotate(x):
    y = x.right
    t = y.left
    y.left = x
    x.right = t
    update(x)
    update(y)
    return y

def right_rotate(y):
    x = y.left
    t = x.right
    x.right = y
    y.left = t
    update(y)
    update(x)
    return x

def rebalance(node):
    update(node)
    bf = balance_factor(node)
    if bf > 1:
        if balance_factor(node.left) < 0:
            node.left = left_rotate(node.left)
        return right_rotate(node)
    if bf < -1:
        if balance_factor(node.right) > 0:
            node.right = right_rotate(node.right)
        return left_rotate(node)
    return node

def insert(node, key):
    if node is None:
        return Node(key)
    if key < node.key:
        node.left = insert(node.left, key)
    elif key > node.key:
        node.right = insert(node.right, key)
    else:
        return node
    update(node)
    return rebalance(node)

def level_order(root):
    if root is None:
        return []
    queue = deque([root])
    result = []
    while queue:
        node = queue.popleft()
        result.append(node.key)
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)
    return result

def avl_level_order_optimal(keys):
